//! Cargo-driven `iexplore.exe` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is iexplore-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind, MsvcrtexKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_wWinMainCRTStartup"),
        "x86_64" => ("x86_64-pc-windows-gnu", "wWinMainCRTStartup"),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "wWinMainCRTStartup"),
        o => panic!("iexplore-cargo: unsupported arch {o}"),
    };

    let late_libs: &[&str] = match arch.as_str() {
        "x86" => &["engine:wine", "sdk/lib/delayimp/libdelayimp_rust.a", "engine:oldnames"],
        "x86_64" => &["engine:wine", "sdk/lib/delayimp/libdelayimp_rust.a", "engine:oldnames"],
        "aarch64" => &["engine:wine", "sdk/lib/delayimp/libdelayimp_rust.a", "engine:oldnames"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("iexplore-rust")
        .resource_from_rc("base/applications/iexplore/iexplore.rc", "iexplore_res")
        .delay_import_lib("dll/win32/advpack/advpack.spec", "advpack.dll", "advpack")
        .delay_import_lib("dll/win32/version/version.spec", "version.dll", "version")
        .delay_import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/ieframe/ieframe.spec", "ieframe.dll", "ieframe")
        .import_lib("dll/win32/msvcrt/msvcrt.spec", "msvcrt.dll", "msvcrt")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // ...and those cmake linked after the body, in the same order.
        .static_libs_after_body(late_libs)
        .msvcrtex_crt(MsvcrtexKind::ExeWide)
        .link(ModuleKind::Win32Exe {
            entry: entry.into(),
            subsystem: "windows:5.01".into(),
        });
}
